def chain_follower(chain):
    chain_dict = {}
    for token in chain:
        if token not in chain_dict:
            chain_dict[token] = []
        chain_dict[token].append(token)

    chain_dict = sorted(chain_dict.items(), key=lambda x: (len(x[1]), x[0]))

    result = []
    current_token = chain_dict[0][0]

    while chain_dict:
        next_token = chain_dict.pop(0)[0]
        result.append(current_token)
        current_token = next_token

    return ','.join(result)
